// Des: Typed errors, exit codes, what-why-fix messages
// Flo: error set > map error to exit code 0-4 > map error to 3-line message
// I/O: anyerror (caller) > u8 exit code + Mesg (stderr text)
// ===================================================================
const std = @import("std"); const vi = @import("er-erro-viet.zig");
const CF = .{ .okay = 0, .fail = 1, .usag = 2, .find = 3, .bloc = 4 };
pub const Erro = error{ NoConsent, ChatFailed, Busy, UnknownModal, Ambiguous, NeedForce, BadUsage, BadConfig, Halted, CapHit, QuietHrs, NoElem, NeedLogin, NoBrowser, BrowFail, Timeout, Closed, BadHandshake, BadFrame, CdpError, TooBig, LaunchTimeout, NoPage, DupSend, BadJob, SqliOpen, SqliExec, SqliPrep, SqliBind, SqliStep, AiFail, HandTask, Fail };
pub const Mesg = vi.Mesg;
pub var viet: bool = true;
pub fn mesgAny(erro: anyerror) Mesg { if (viet) return vi.mesg(erro); return mesg(erro); }
pub fn exitCode(erro: anyerror) u8 { return switch (erro) { error.BadUsage, error.BadJob, error.BadConfig => CF.usag, error.NoElem, error.Ambiguous => CF.find, error.Halted, error.CapHit, error.QuietHrs, error.NeedLogin, error.NeedForce, error.Busy, error.UnknownModal, error.ChatFailed, error.NoConsent, error.HandTask => CF.bloc, else => CF.fail }; }
pub fn mesg(erro: anyerror) Mesg { return switch (erro) { error.BadUsage => .{ .what = "bad usage", .whyz = "unknown command or flag", .fixz = "run: za-zalo-webs help" }, error.BadJob => .{ .what = "bad job", .whyz = "unknown job name or missing arguments", .fixz = "run: za-zalo-webs help" }, error.BadConfig => .{ .what = "bad config", .whyz = "aa-conf-main.json has a bad value", .fixz = "fix the key or delete the file for defaults" }, error.Halted => .{ .what = "halted", .whyz = "captcha, lock, warning, logout or login-elsewhere seen", .fixz = "open Zalo by hand, clear it, then run: za-zalo-webs resume" }, error.CapHit => .{ .what = "cap reached", .whyz = "hour or day send cap used up", .fixz = "wait for the window to reset or raise the cap slowly" }, error.QuietHrs => .{ .what = "quiet hours", .whyz = "now is inside quiet_hour_rang", .fixz = "run later or change quie_hour_rang" }, error.NoElem => .{ .what = "element missing", .whyz = "page label not found after retries (UI drift)", .fixz = "run the canary, update label names in config" }, error.NeedLogin => .{ .what = "login needed", .whyz = "Zalo Web shows the QR page", .fixz = "run: za-zalo-webs login and scan the QR with the Zalo phone app" }, error.NoBrowser => .{ .what = "no browser", .whyz = "Chrome or Edge not found", .fixz = "install Chrome or set brow_exec_path" }, error.BrowFail => .{ .what = "browser failed", .whyz = "launch or page command failed", .fixz = "close other za runs, retry" }, error.Timeout => .{ .what = "timeout", .whyz = "no answer in time", .fixz = "retry later" }, error.LaunchTimeout => .{ .what = "browser start timeout", .whyz = "no debug port file appeared", .fixz = "close Chrome windows using the za profile, retry" }, error.NoConsent => .{ .what = "risk not accepted", .whyz = "Zalo does not allow automation; you must accept the risk once", .fixz = "run: za-zalo-webs setup --yes" }, error.ChatFailed => .{ .what = "chat refused a send", .whyz = "a send to this chat failed in the last 24 hours", .fixz = "check the chat by hand (blocked or removed?) before trying again" }, error.Busy => .{ .what = "already running", .whyz = "another za-zalo-webs run holds the lock", .fixz = "wait for it to finish or run: za-zalo-webs status" }, error.UnknownModal => .{ .what = "unknown popup", .whyz = "a dialog za does not know blocks the page", .fixz = "close it by hand, then run again" }, error.Ambiguous => .{ .what = "ambiguous name", .whyz = "more than one chat has this name", .fixz = "add #group or #person after the name" }, error.NeedForce => .{ .what = "needs force", .whyz = "bulk, group or new-recipient action is ask-first", .fixz = "re-run with --live --force after checking the preview" }, error.DupSend => .{ .what = "duplicate send", .whyz = "same chat and text already sent", .fixz = "nothing to do" }, error.HandTask => .{ .what = "your turn", .whyz = "this step (password, code, QR) is for you only; za never types secrets", .fixz = "finish it in the browser window, then run za again" }, error.AiFail => .{ .what = "AI failed", .whyz = "AI adapter answered nothing", .fixz = "turn off smar_mode_enab or fix the command" }, else => .{ .what = "failed", .whyz = @errorName(erro), .fixz = "re-run with --json and check status" } }; }
